// In-memory push gate: quiet hours and a daily cap, both in the user's own time zone.

const HISTORY_KEEP_MS = 3 * 24 * 60 * 60 * 1000; // longer than any local-day length plus zone offset change

const formatters = new Map();

function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    // Throws RangeError for an unknown zone.
    f = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Returns { day: "YYYY-MM-DD", minutes: minutes since local midnight } for the instant in the zone.
function localTime(date, timeZone) {
  const parts = {};
  for (const p of formatterFor(timeZone).formatToParts(date)) parts[p.type] = p.value;
  return {
    day: `${parts.year}-${parts.month}-${parts.day}`,
    minutes: Number(parts.hour) * 60 + Number(parts.minute),
  };
}

function parseClock(value) {
  const m = typeof value === 'string' ? /^([01]\d|2[0-3]):([0-5]\d)$/.exec(value) : null;
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

function inQuietHours(minutes, start, end) {
  if (start === end) return false; // empty window: the user set no quiet period
  if (start < end) return minutes >= start && minutes < end;
  return minutes >= start || minutes < end; // runs past midnight
}

const deny = (reason) => ({ allowed: false, reason });

export function createPushGate() {
  const sentByUser = new Map(); // user id -> array of send times (ms since epoch)

  function attempt(user, now) {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny('invalid_time');
    if (!user || typeof user.id !== 'string' || user.id === '') return deny('invalid_user_settings');

    const start = parseClock(user.quietStart);
    const end = parseClock(user.quietEnd);
    const cap = user.dailyCap;
    if (start === null || end === null || !Number.isInteger(cap) || cap < 0) {
      return deny('invalid_user_settings');
    }

    let local;
    try {
      local = localTime(now, user.timeZone);
    } catch {
      return deny('invalid_user_settings');
    }

    if (inQuietHours(local.minutes, start, end)) return deny('quiet_hours');

    // "Day" is the user's local calendar day, using the zone passed in this call.
    const nowMs = now.getTime();
    const history = (sentByUser.get(user.id) ?? []).filter((t) => t > nowMs - HISTORY_KEEP_MS);
    const sentToday = history.filter((t) => localTime(new Date(t), user.timeZone).day === local.day).length;

    if (sentToday >= cap) {
      sentByUser.set(user.id, history);
      return deny('daily_cap_reached');
    }

    history.push(nowMs);
    sentByUser.set(user.id, history);
    return { allowed: true, reason: null };
  }

  return { attempt };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/courier-inv-g2-2/bot.mjs';

const tokyo = { id: 'u1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (s) => new Date(s);

// Tokyo = UTC+9. 12:00 UTC = 21:00 JST (ok); 13:00 UTC = 22:00 JST (quiet).
let g = createPushGate();
assert.deepEqual(g.attempt(tokyo, at('2026-10-22T12:00:00Z')), { allowed: true, reason: null });
assert.equal(g.attempt(tokyo, at('2026-10-22T13:00:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(tokyo, at('2026-10-22T21:59:00Z')).reason, 'quiet_hours'); // 06:59 JST
assert.equal(g.attempt(tokyo, at('2026-10-22T22:00:00Z')).allowed, true); // 07:00 JST boundary, new local day

// Cap: quiet-denied calls don't count; 3 allowed then cap; next local day resets.
g = createPushGate();
for (let i = 0; i < 3; i++) assert.equal(g.attempt(tokyo, at(`2026-10-22T0${i}:00:00Z`)).allowed, true);
assert.equal(g.attempt(tokyo, at('2026-10-22T05:00:00Z')).reason, 'daily_cap_reached');
assert.equal(g.attempt(tokyo, at('2026-10-22T14:00:00Z')).reason, 'quiet_hours'); // 23:00 JST
// 2026-10-23 00:00 JST is quiet; 07:00 JST = 22:00 UTC the 22nd, next local day.
assert.equal(g.attempt(tokyo, at('2026-10-22T22:00:00Z')).allowed, true);

// Local day, not UTC day: LA 17:00 PDT = 00:00 UTC next day, still same local day.
const la = { id: 'u2', timeZone: 'America/Los_Angeles', quietStart: '22:00', quietEnd: '07:00', dailyCap: 1 };
g = createPushGate();
assert.equal(g.attempt(la, at('2026-10-22T16:00:00Z')).allowed, true); // 09:00 PDT
assert.equal(g.attempt(la, at('2026-10-23T00:30:00Z')).reason, 'daily_cap_reached'); // 17:30 PDT same day
assert.equal(g.attempt(la, at('2026-10-23T16:00:00Z')).allowed, true); // next day

// Non-wrapping window, equal window, cap 0, isolation, per-call settings.
const nap = { id: 'u3', timeZone: 'UTC', quietStart: '13:00', quietEnd: '15:00', dailyCap: 5 };
g = createPushGate();
assert.equal(g.attempt(nap, at('2026-10-22T14:00:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(nap, at('2026-10-22T15:00:00Z')).allowed, true);
assert.equal(g.attempt({ ...nap, dailyCap: 0 }, at('2026-10-22T16:00:00Z')).reason, 'daily_cap_reached');
assert.equal(g.attempt({ ...nap, dailyCap: 2 }, at('2026-10-22T17:00:00Z')).allowed, true);
assert.equal(g.attempt({ ...nap, dailyCap: 2 }, at('2026-10-22T18:00:00Z')).reason, 'daily_cap_reached');
assert.equal(createPushGate().attempt({ ...nap, dailyCap: 1 }, at('2026-10-22T18:00:00Z')).allowed, true);

// DST: Europe/Berlin falls back 2026-10-25; local day has 25h, still one day.
const be = { id: 'u4', timeZone: 'Europe/Berlin', quietStart: '22:00', quietEnd: '07:00', dailyCap: 2 };
g = createPushGate();
assert.equal(g.attempt(be, at('2026-10-24T22:30:00Z')).allowed, true); // 00:30 CEST? quiet check below

